import React from "react";
import Header from "./components/Header";
import Skills from "./components/Skills";
import Projects from "./components/Projects";
import Contact from "./components/Contact";
import "./App.css";


function App() {
  return (
    <div>
      <Header />

      <section id="about">
        <h2>About Me</h2>
        <p>
          I am Yvette, a passionate learner in web development and data science. I
          love creating useful projects to solve real problems.
        </p>
      </section>

      <Skills />

      <Projects />

      <Contact />
    </div>
  );
}

export default App;
